Definition large_alloc_seg2b_post (sp gp tp t0 t1 t2 a6 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo size msz a pa nres : Z) (stat : word) : machine_state -> Prop :=
  fun ms' => exists m' (j44 : list byte),
    ms' = MS (mkR (wz 0x088a18) (Z_to_bv 64 (bv_unsigned sp + -192)) gp tp t0 t1 t2 (wz 0x20000) (wz 0) (wz (pa + 8 * nres)) (wz 0x20000) (wz 3) (wz 50) (Z_to_bv 64 (-1)) (wz 0) a6 (wz 222)
                  (wz (pa + 8 * nres)) (wz 0) (wz APAGESZ) (wz a) (wz (a + msz)) (wz (a + 4096 + size)) (wz 7) (wz (a + 4096)) s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x086c58) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 464, bv_unsigned sp + -96)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -192)
    /\ rw_cells bsegs m' (bv_unsigned sp + -192) [C4 (wz 50); CB 44 j44; C8 (wz (a + 4096)); C8 (wz (clzbits msz)); C8 (wz msz); C8 (wz (AINST + 64)); C8 stat; C8 (wz 0x54f48)].

Section Seg2b.
  Variables (sp gp tp t0 t1 t2 a1 a2 a5 a6 a7 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (stat : word) (lo size msz a pa nres TSD CTX TH : Z).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -96).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 464 <= bv_unsigned sp.
  Hypothesis SZ : 0x10000 < size /\ size <= 2^41. Hypothesis MSZ : size + 4096 <= msz /\ msz < size + 8192.
  Hypothesis AR : aapp a msz /\ a + msz <= aceil.
  Hypothesis PAR : aapp pa kPtrArrayReserve /\ pa + kPtrArrayReserve <= aceil /\ pa mod 4096 = 0.
  Hypothesis NCH : 0 <= nres /\ nres + 16384 <= 2^20. Hypothesis NRQ : exists q, nres = 512 * q.
  Hypothesis ENV : SENV tp TSD CTX TH m.
  Hypothesis INST64 : rw_cells bsegs m 1221016 [C8 (wz 4096); C8 (wz pa); C8 (wz pa)].
  Hypothesis NRES : rw_cells bsegs m 1221064 [C8 (wz nres); C8 (wz nres); C8 (wz 0)].

  Let ARE : 6832128 <= a /\ a + msz <= aceil. Proof. exact (aapp_env _ _ (proj1 AR) ltac:(lia)). Qed.   (* [comment removed for export] *)
  Let PAE : 6832128 <= pa /\ pa + kPtrArrayReserve <= aceil. Proof. exact (aapp_env _ _ (proj1 PAR) ltac:(clear; hci; unfold kPtrArrayReserve; lia)). Qed.
