Definition large_alloc_seg4_post (sp gp tp t0 t1 t2 a6 a7 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo size msz a nres : Z) (stat : word) : machine_state -> Prop :=
  fun ms' => exists (a1 a2 a4 a5 : word) m',
    ms' = MS (mkR (wz 0x54f48) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2
                  stat (wz (AINST + 64)) (wz (a + 4096)) a1 a2 (wz nres) a4 a5 a6 a7
                  (wz msz) (wz (clzbits msz)) (wz (a + 4096)) (wz a) (wz (a + msz)) (wz (a + 4096 + size)) (wz 7) (wz (a + 4096)) s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x54d50) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 192, bv_unsigned sp + -96); (1221064, 1221072)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -96)
    /\ rw_cells bsegs m' 1221064 [C8 (wz (nres + 16384)); C8 (wz nres); C8 (wz 0)].

Section Seg4.
  Variables (sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (stat : word) (j44 : list byte) (lo size msz a pa nres TSD CTX TH : Z).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -192).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 464 <= bv_unsigned sp. Hypothesis SPH : bv_unsigned sp + 16 <= 2^47.
  Hypothesis SPA : hidden (bv_unsigned sp mod 16 = 0).
  Hypothesis AR : aapp a msz /\ a + msz <= aceil. Hypothesis MSZ : size + 4096 <= msz.
  Hypothesis PAR : aapp pa kPtrArrayReserve /\ pa + kPtrArrayReserve <= aceil.
  Hypothesis NCH : 0 <= nres /\ nres + 16384 <= 2^20.
  Hypothesis ENV : SENV tp TSD CTX TH m.
  Hypothesis FR2 : rw_cells bsegs m (bv_unsigned sp + -192) [C4 (wz 50); CB 44 j44; C8 (wz (a + 4096)); C8 (wz (clzbits msz)); C8 (wz msz); C8 (wz (AINST + 64)); C8 stat; C8 (wz 0x54f48)].
  Hypothesis NRES : rw_cells bsegs m 1221064 [C8 (wz nres); C8 (wz nres); C8 (wz 0)].

  Let ARE : 6832128 <= a /\ a + msz <= aceil. Proof. pose proof (proj1 AR) as X. clear - X. aunf. lia. Qed.   (* [comment removed for export] *)
  Let PAE : 6832128 <= pa /\ pa + kPtrArrayReserve <= aceil. Proof. exact (aapp_env _ _ (proj1 PAR) ltac:(clear; hci; unfold kPtrArrayReserve; lia)). Qed.
Scheme kc__5 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.Bo.AllocWalkKit.hidden Sort Prop.   (* [comment removed for export] *)
  Theorem large_alloc_seg4 :
    evt bsegs (large_alloc_seg4_post sp gp tp t0 t1 t2 a6 a7 s10 s11 t3 t4 t5 t6 F fc m lo size msz a nres stat)
      (MS (mkR (wz 0x088a18) (Z_to_bv 64 (bv_unsigned sp + -192)) gp tp t0 t1 t2 (wz 0x20000) (wz 0) (wz (pa + 8 * nres)) a1 a2 a3 a4 a5 a6 a7
                  (wz (pa + 8 * nres)) (wz 0) (wz APAGESZ) (wz a) (wz (a + msz)) (wz (a + 4096 + size)) (wz 7) (wz (a + 4096)) s10 s11 t3 t4 t5 t6)
